const READWISE_TOKEN = "￼".trim();

const content = selector => document.querySelector(selector)?.content?.trim() || "";
const contents = selector => [...document.querySelectorAll(selector)]
  .map(element => element.content?.trim())
  .filter(Boolean);
const unique = values => [...new Set(values.map(value => String(value).trim()).filter(Boolean))];

const jsonLdNodes = [...document.querySelectorAll('script[type="application/ld+json"]')]
  .flatMap(script => {
    try {
      const parsed = JSON.parse(script.textContent);
      const nodes = Array.isArray(parsed) ? parsed : [parsed];
      return nodes.flatMap(node => node?.["@graph"] || node);
    } catch {
      return [];
    }
  });

const articleTypes = new Set(["Article", "NewsArticle", "BlogPosting", "ReportageNewsArticle"]);
const articleData = jsonLdNodes.find(node => {
  const types = Array.isArray(node?.["@type"]) ? node["@type"] : [node?.["@type"]];
  return types.some(type => articleTypes.has(type));
}) || {};

const names = value => {
  const entries = Array.isArray(value) ? value : value ? [value] : [];
  return unique(entries.flatMap(entry => {
    if (typeof entry === "string") return [entry];
    return [entry?.name, entry?.givenName && entry?.familyName
      ? `${entry.givenName} ${entry.familyName}`
      : ""];
  }));
};

const imageUrl = value => {
  const entry = Array.isArray(value) ? value[0] : value;
  return typeof entry === "string" ? entry : entry?.url || entry?.contentUrl || "";
};

const isoDate = value => {
  if (!value) return "";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : date.toISOString();
};

const canonical = document.querySelector('link[rel="canonical"]')?.href || location.href;
const title = articleData.headline || content('meta[property="og:title"]') || document.title;
const author = names(articleData.author).join(", ") ||
  content('meta[name="author"]') ||
  content('meta[name="parsely-author"]');
const summary = articleData.description ||
  content('meta[name="description"]') ||
  content('meta[property="og:description"]') ||
  content('meta[name="twitter:description"]');
const publishedDate = isoDate(
  articleData.datePublished ||
  content('meta[property="article:published_time"]') ||
  content('meta[name="parsely-pub-date"]') ||
  document.querySelector("time[datetime]")?.dateTime
);
const coverImage = imageUrl(articleData.image) ||
  content('meta[property="og:image"]') ||
  content('meta[name="twitter:image"]') ||
  content('meta[name="parsely-image-url"]');
const publication = names(articleData.publisher).join(", ") ||
  content('meta[property="og:site_name"]');

const keywordValues = [
  ...(Array.isArray(articleData.keywords)
    ? articleData.keywords
    : String(articleData.keywords || "").split(",")),
  ...contents('meta[property="article:tag"]'),
  ...content('meta[name="keywords"]').split(",")
];
const tags = unique(["medium", ...keywordValues]).slice(0, 20);

if (!READWISE_TOKEN || READWISE_TOKEN === "PASTE_READWISE_TOKEN") {
  completion("Readwise-Token fehlt. Öffne den Kurzbefehl und trage ihn in der ersten Text-Aktion ein.");
} else {
  const payload = {
    url: canonical,
    html: document.documentElement.outerHTML,
    should_clean_html: true,
    title,
    category: "article",
    location: "new",
    saved_using: "iOS Safari Full HTML + Metadata"
  };

  if (author) payload.author = author;
  if (summary) payload.summary = summary;
  if (publishedDate) payload.published_date = publishedDate;
  if (coverImage) payload.image_url = coverImage;
  if (tags.length) payload.tags = tags;
  if (publication) payload.notes = `Publication: ${publication}`;

  fetch("https://readwise.io/api/v3/save/", {
    method: "POST",
    headers: {
      "Authorization": `Token ${READWISE_TOKEN}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(payload)
  })
  .then(async response => {
    const text = await response.text();
    if (!response.ok) {
      completion(`Readwise-Fehler ${response.status}: ${text}`);
      return;
    }
    completion(`Artikel mit Metadaten gespeichert.\nAutor: ${author || "nicht gefunden"}\nDatum: ${publishedDate || "nicht gefunden"}\nTags: ${tags.length}`);
  })
  .catch(error => completion(`Übertragung fehlgeschlagen: ${error.message}`));
}
